CREATE TEMP TABLE institution (institution_id text, time_zone text) ON COMMIT DROP;
CREATE TEMP TABLE account (account_id uuid, institution_id text, role_id text, test_account boolean, created timestamptz) ON COMMIT DROP;
CREATE TEMP TABLE course (course_id uuid, title text) ON COMMIT DROP;
CREATE TEMP TABLE course_module (course_module_id uuid, course_id uuid, title text, display_order integer) ON COMMIT DROP;
CREATE TEMP TABLE course_unit (course_unit_id uuid, course_module_id uuid, title text, course_unit_type_id text, reporting_key text, display_order integer) ON COMMIT DROP;
CREATE TEMP TABLE institution_course (institution_id text, course_id uuid, display_order integer) ON COMMIT DROP;
CREATE TEMP TABLE mv_analytics_dwell_time (institution_id text, account_id uuid, course_unit_id uuid, session_id uuid, page_view_type text, dwell_time_seconds numeric, page_viewed_at timestamptz) ON COMMIT DROP;
CREATE TEMP TABLE mv_analytics_course_unit_video_segment (institution_id text, account_id uuid, course_unit_id uuid, previous_event_at timestamptz, event_at timestamptz, watched_interval_start_seconds double precision, watched_interval_end_seconds double precision, watched_seconds_delta double precision) ON COMMIT DROP;

-- Same-institution event referencing an account from another institution is excluded.
-- A course unit that is not associated with this institution is excluded.
